"use client";

import { useEffect, useState, useRef } from "react";
import { cn } from "../../lib/utils";

interface HeadingItem {
  text: string;
  id: string;
  level: number;
}

export function TableOfContents({ headings }: { headings: HeadingItem[] }) {
  const [activeId, setActiveId] = useState<string>("");
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => {
    const handleObserver = (entries: IntersectionObserverEntry[]) => {
      const visibleEntries = entries.filter((entry) => entry.isIntersecting);

      if (visibleEntries.length > 0) {
        // Sort by how close they are to the top of the viewport
        const sorted = visibleEntries.sort(
          (a, b) => a.boundingClientRect.top - b.boundingClientRect.top
        );
        setActiveId(sorted[0].target.id);
      }
    };

    observer.current = new IntersectionObserver(handleObserver, {
      rootMargin: "-100px 0px -70% 0px", // Offset for top nav bar and viewport center focus
    });

    headings.forEach((heading) => {
      const el = document.getElementById(heading.id);
      if (el) observer.current?.observe(el);
    });

    return () => observer.current?.disconnect();
  }, [headings]);

  if (headings.length === 0) return null;

  return (
    <nav className="space-y-4 sticky">
      <div className="relative border-l border-zinc-900 ml-1 py-1 space-y-3.5">
        {headings.map((heading) => {
          const isActive = activeId === heading.id;
          return (
            <a
              key={heading.id}
              href={`#${heading.id}`}
              className={cn(
                "block font-mono text-[11px] font-medium tracking-wide transition-all duration-normal border-l-2 -ml-px pl-4 hover:text-white leading-relaxed",
                heading.level === 3 ? "pl-8 text-[10px]" : "",
                isActive
                  ? "text-primary border-primary font-bold"
                  : "text-zinc-500 border-transparent"
              )}
            >
              {heading.text}
            </a>
          );
        })}
      </div>
    </nav>
  );
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}

export { cn } from "cn"

export const currentYear = new Date().getFullYear().toString();
export function formatDate(date: string | Date): string {
  const dateObj = typeof date === "string" ? new Date(date) : date
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(dateObj)
}
